function parseCsv(text) {
  const [header, ...rows] = text.split("\n");
  const columns = header.split(",");
  return rows.map((row) => Object.fromEntries(row.split(",").map((value, index) => [columns[index], value])));
}

function total(rows) {
  return rows.reduce((sum, row) => sum + Number(row.amount), 0);
}

module.exports = { parseCsv, total };

const test = require("node:test");
const assert = require("node:assert/strict");
const { parseCsv, total } = require("../src/csv.js");

test("reads header", () => {
  assert.deepEqual(parseCsv("date,amount\n2026-10-01,1200"), [{ date: "2026-10-01", amount: "1200" }]);
});

test("sums amounts", () => {
  assert.equal(total([{ amount: "1200" }, { amount: "800" }]), 2000);
});

test("parses empty csv", () => {
  assert.deepEqual(parseCsv("date,amount\n"), []);
});

test("rounds totals", () => {
  assert.equal(total([{ amount: "0.1" }, { amount: "0.2" }]), 0.3);
});
